                  dict(label='Estructuras en el límite', points=[dict(text='Mycoplasma genitalium mide 0,2 µm = 200 nm, justo el límite óptico; un lisosoma de 0,02 a 0,5 µm (20 a 500 nm) se resuelve solo si está en la parte alta del intervalo.', quotes=[Q('es_celula', 'más pequeña observada, en condiciones normales, corresponde a Mycoplasma genitalium, de 0,2 μm'), Q('es_lisosoma', 'El tamaño de un lisosoma varía entre 0,02~0,5 μm.')])]),
                  dict(label='Estructuras pequeñas', points=[dict(text='Un microtúbulo de 25 nm de diámetro es ocho veces menor que 200 nm: solo puede resolverse con microscopio electrónico, cuyo límite de 0,1 nm queda muy por debajo de 25 nm.', quotes=[Q('en_cytoskeleton', 'Microtubules are composed of tubulin and are 25 nm in diameter.'), Q('en_em', 'As the wavelength of an electron can be more than 100,000 times smaller than that of visible light, electron microscopes have a much higher resolution of about 0.1 nm, which compares to about 200 nm for light microscopes.')])]),
